// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Roulette} from "../src/Roulette.sol";

contract InvMutTest is Test {
    Roulette c;
    function setUp() public { c = new Roulette{value: 10 ether}(); }

    function testFuzz_property(uint256 ts, address actor) public {
        vm.assume(ts > 0);
        vm.assume(actor != address(c) && actor != address(this));
        vm.deal(actor, 20 ether);
        vm.warp(ts);
        vm.roll(14); // non-winning block, no payout side effects

        vm.prank(actor);
        (bool ok1,) = address(c).call{value: 10 ether}("");
        assertTrue(ok1, "first call should succeed");

        // Second call at the SAME timestamp: the reference requires
        // block.timestamp > pastBlockTime, so it must revert.
        vm.warp(ts);
        vm.prank(actor);
        (bool ok2,) = address(c).call{value: 10 ether}("");
        assertTrue(!ok2, "a second call in the same block-time must revert");
    }
}
